def solve(inp,mark):
    S=[(r,c) for r in range(len(inp)) for c in range(len(inp[0])) if inp[r][c]==mark]
    H,W=len(inp),len(inp[0])
    pred=[row[:] for row in inp]
    for dr in range(-H,H):
        for dc in range(-W,W):
            sh=[(r+dr,c+dc) for r,c in S]
            if all(0<=r<H and 0<=c<W and inp[r][c]==0 for r,c in sh):
                for r,c in sh: pred[r][c]=mark
    return pred
